import {test} from 'node:test';import assert from 'node:assert/strict';import {queue} from '../src/queue.mjs';import {work} from '../src/worker.mjs';
test('bounded batch retries once, preserving payload and order',()=>{const q=queue([{id:'a',payload:1},{id:'b',payload:2},{id:'c',payload:3}]);const seen=[];assert.equal(q.snapshot().ready.length,3);assert.deepEqual(work(q,j=>{seen.push(j.id);return j.id==='b';},2),{sent:['b'],retried:['a']});assert.deepEqual(seen,['a','b']);assert.deepEqual(q.snapshot(),{ready:[{id:'c',payload:3},{id:'a',payload:1}],leased:[]});});
test('zero and invalid limit do no work',()=>{const q=queue([{id:'a'}]);const before=q.snapshot();assert.deepEqual(work(q,()=>assert.fail(),0),{sent:[],retried:[]});assert.throws(()=>work(q,()=>assert.fail(),-1),TypeError);assert.deepEqual(q.snapshot(),before);});
test('all failures at most once per initial job',()=>{const q=queue([{id:'a'},{id:'b'}]);const seen=[];assert.deepEqual(work(q,j=>{seen.push(j.id);return false;},8),{sent:[],retried:['a','b']});assert.deepEqual(seen,['a','b']);assert.deepEqual(q.snapshot(),{ready:[{id:'a'},{id:'b'}],leased:[]});});
test('unsafe integer is rejected before send',()=>{const q=queue([{id:'a'}]);assert.throws(()=>work(q,()=>assert.fail(),Number.MAX_SAFE_INTEGER+1),TypeError);assert.deepEqual(q.snapshot(),{ready:[{id:'a'}],leased:[]});});
